import type { DiscoverLesson, DiscoverStep } from "@/types/discover";

type DeepStepDraft = Omit<DiscoverStep, "id" | "imageUrl">;

function deepLesson(input: {
  id: string;
  title: string;
  summary: string;
  category: string;
  accent: DiscoverLesson["accent"];
  durationMinutes: number;
  steps: DeepStepDraft[];
  takeaways: string[];
}): DiscoverLesson {
  return {
    ...input,
    coverImageUrl: `/discover/deep/${input.id}-cover.svg`,
    coverImageAlt: `${input.title} illustrated concept overview.`,
    difficulty: "intermediate",
    published: true,
    featured: false,
    createdAt: 1791676800000,
    updatedAt: 1791676800000,
    steps: input.steps.map((step, index) => ({
      ...step,
      id: `${input.id}-${index + 1}`,
      imageUrl: `/discover/deep/${input.id}-${index + 1}.svg`,
    })),
  };
}

